/**
 * The mode-chip corpus — 189 snapshots, one per (preset, mode).
 *
 * A property test says "the chip always fits". A corpus says "on 2026-11-15,
 * at 1280×720, the classic mode needed 246px of 1072 and said so". The second is
 * what turns a future regression into a diff instead of an argument, and it is
 * the only artefact that survives a refactor of the planner's internals.
 *
 * The files are generated by `scripts/gen-mode-chip-fixtures.ts` and are checked
 * two ways: this test recomputes each one from the modules (so a stale corpus is
 * a red test, not a stale green), and it also asserts the internal consistency of
 * each snapshot on its own terms — the two can disagree, and when they do the
 * interesting question is which one is wrong.
 */
import { describe, expect, it } from "vitest";
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";

import { MODE_LIST } from "../src/game/modes";
import { PRESETS } from "../src/components/menu/adaptive/presets";
import { heroBandWidth } from "../src/components/menu/adaptive/hero";
import { planModeChip } from "../src/components/menu/adaptive/chip";

const CORPUS = join("tests", "fixtures", "mode-chips");
const FILES = readdirSync(CORPUS).filter((f) => f.endsWith(".json")).sort();

interface Snapshot {
  preset: string;
  window: string;
  mode: string;
  name: string;
  band: number;
  visible: boolean;
  align: string;
  showLabel: boolean;
  nameSize: number;
  labelSize: number;
  maxWidth: number;
  needed: number;
  available: number;
  truncated: boolean;
  reason: string;
}

const snapshots: Snapshot[] = FILES.map((f) => JSON.parse(readFileSync(join(CORPUS, f), "utf8")) as Snapshot);

describe("the mode-chip corpus", () => {
  it("holds one file per (preset, mode)", () => {
    expect(FILES.length).toBe(PRESETS.length * MODE_LIST.length);
    expect(FILES.length).toBe(189);
  });

  it("names its own inputs", () => {
    for (const s of snapshots) {
      expect(PRESETS.some((p) => p.id === s.preset), s.preset).toBe(true);
      expect(MODE_LIST.some((m) => m.id === s.mode), s.mode).toBe(true);
      const preset = PRESETS.find((p) => p.id === s.preset)!;
      expect(s.window).toBe(`${preset.width}×${preset.height}`);
      expect(s.band).toBe(heroBandWidth(preset.width));
    }
  });

  it("still matches what the planner produces", () => {
    for (const s of snapshots) {
      const mode = MODE_LIST.find((m) => m.id === s.mode)!;
      const plan = planModeChip({ heroWidth: s.band, side: "right", name: mode.name, label: "CHẾ ĐỘ CHƠI" });
      expect(
        {
          visible: plan.visible,
          align: plan.align,
          showLabel: plan.showLabel,
          nameSize: plan.nameSize,
          labelSize: plan.labelSize,
          maxWidth: plan.maxWidth,
          needed: plan.needed,
          available: plan.available,
          truncated: plan.truncated,
          reason: plan.reason,
        },
        `${s.preset}--${s.mode}`,
      ).toEqual({
        visible: s.visible,
        align: s.align,
        showLabel: s.showLabel,
        nameSize: s.nameSize,
        labelSize: s.labelSize,
        maxWidth: s.maxWidth,
        needed: s.needed,
        available: s.available,
        truncated: s.truncated,
        reason: s.reason,
      });
    }
  });

  it("is internally consistent, so a corrupted file is caught even if it round-trips", () => {
    for (const s of snapshots) {
      const label = `${s.preset}--${s.mode}`;
      expect(s.available, label).toBe(Math.max(0, s.band - 16));
      if (!s.visible) {
        expect(s.maxWidth, label).toBe(0);
        expect(s.reason, label).toBe("hidden");
        continue;
      }
      expect(s.maxWidth, label).toBeLessThanOrEqual(s.available);
      expect(s.align, label).toBe("end");
      expect(s.nameSize, label).toBeGreaterThanOrEqual(9.5);
      if (!s.truncated) expect(s.needed, label).toBeLessThanOrEqual(s.available);
      // The ladder's own ordering: no name-size growth as the band shrinks is
      // impossible to check from one file, so check the rung against the sizes.
      if (s.reason === "full") expect(s.showLabel, label).toBe(true);
      if (s.reason === "label-dropped") expect(s.showLabel, label).toBe(false);
      if (s.reason === "ellipsis") expect(s.nameSize, label).toBe(9.5);
    }
  });

  it("keeps the classic mode intact at every preset — the reported bug", () => {
    const classic = snapshots.filter((s) => s.mode === "classic");
    expect(classic.length).toBe(PRESETS.length);
    for (const s of classic) {
      expect(s.visible, s.preset).toBe(true);
      expect(s.showLabel, s.preset).toBe(true);
      expect(s.truncated, s.preset).toBe(false);
      expect(s.reason, s.preset).toBe("full");
      expect(s.needed, s.preset).toBe(246);
    }
  });

  it("grows the chip only with the mode name, never with the window", () => {
    // For one mode, `needed` is the same at 320 and at 4K — it is a text width.
    for (const mode of MODE_LIST) {
      const forMode = snapshots.filter((s) => s.mode === mode.id).map((s) => s.needed);
      expect(new Set(forMode).size, mode.id).toBe(1);
    }
  });
});
